-- Baseline of the rewrite (epic #371, step B0 #372; docs/rewrite/10-conclusion.md). It replaces the 36
-- migrations of the first app and is applied to databases created new: no data is carried over.
-- Its name differs from the old 0001_baseline.sql on purpose, so applying it to an old database
-- fails loudly on the first CREATE TABLE instead of being skipped as "already applied".
-- All ids are UUIDs generated by the client, so rows created offline can be synced later.

-- ---------------------------------------------------------------- accounts and tenancy (kept)
CREATE TABLE users (
  id             TEXT PRIMARY KEY,
  email          TEXT NOT NULL,
  name           TEXT,
  password_hash  TEXT NOT NULL,                 -- 'pbkdf2-sha256$<iterations>$<salt>$<hash>'; '!' = sign-in disabled
  status         TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'blocked')),
  failed_logins  INTEGER NOT NULL DEFAULT 0,
  locked_until   TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at     TEXT
);
CREATE UNIQUE INDEX users_email_idx ON users (email COLLATE NOCASE);

-- The raw token is never stored: id is its SHA-256 (hex).
CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client        TEXT NOT NULL CHECK (client IN ('dashboard', 'mobile')),
  expires_at    TEXT NOT NULL,
  last_used_at  TEXT,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX sessions_user_idx ON sessions (user_id, expires_at);

-- Access is decided by workspace_members alone; owner_user_id is bookkeeping.
CREATE TABLE workspaces (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  owner_user_id  TEXT REFERENCES users(id),
  kind           TEXT NOT NULL DEFAULT 'shared' CHECK (kind IN ('personal', 'shared')),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at     TEXT
);
CREATE INDEX workspaces_owner_idx ON workspaces (owner_user_id);

CREATE TABLE workspace_members (
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role          TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'editor', 'viewer')),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX workspace_members_user_idx ON workspace_members (user_id);

-- A project is a root of files and a hard scope: nothing moves between projects.
CREATE TABLE projects (
  id            TEXT PRIMARY KEY,
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id),
  name          TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT
);
CREATE UNIQUE INDEX projects_workspace_name_idx ON projects (workspace_id, name COLLATE NOCASE);

-- ---------------------------------------------------------------- files
-- Everything a user makes is a file (docs/rewrite/07-organisation.md). The columns are the same for
-- every type; what a type saves whole is its body, checked by @openclapper/model on every save.
-- A file belongs to exactly one root: a project, or the account home of one user.
CREATE TABLE files (
  id            TEXT PRIMARY KEY,
  project_id    TEXT REFERENCES projects(id) ON DELETE CASCADE,
  home_of       TEXT REFERENCES users(id) ON DELETE CASCADE,
  type          TEXT NOT NULL,
  name          TEXT NOT NULL,                  -- free text, not unique
  -- The folder or collection it sits in; NULL = the top level of its root. When a container is
  -- purged, what was binned on its own inside it stays in the bin and comes back at the top level.
  container     TEXT REFERENCES files(id) ON DELETE SET NULL,
  -- The file it was made inside (an internal file): in no container, shown inside its parent, gone with it.
  internal_of   TEXT REFERENCES files(id) ON DELETE CASCADE,
  fixed         TEXT CHECK (fixed IN ('desktop', 'settings')),  -- a project's fixed folders
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT,
  created_by    TEXT REFERENCES users(id) ON DELETE SET NULL,
  -- The recycle bin: deleted_at marks a binned file; deleted_with names the file whose binning took
  -- this one along (a folder's contents, a file's internal files), NULL for the one the user binned.
  deleted_at    TEXT,
  deleted_with  TEXT,
  -- One editor at a time, whichever window edits: the user, the window's own token, and until when.
  lock_by       TEXT REFERENCES users(id) ON DELETE SET NULL,
  lock_holder   TEXT,
  lock_until    TEXT,
  body          TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(body) AND json_type(body) = 'object'),
  body_version  INTEGER NOT NULL DEFAULT 1,
  CHECK ((project_id IS NULL) != (home_of IS NULL)),
  CHECK (container IS NULL OR internal_of IS NULL)
);
CREATE INDEX files_project_idx   ON files (project_id, type) WHERE project_id IS NOT NULL;
CREATE INDEX files_home_idx      ON files (home_of, type) WHERE home_of IS NOT NULL;
CREATE INDEX files_container_idx ON files (container) WHERE container IS NOT NULL;
CREATE INDEX files_internal_idx  ON files (internal_of) WHERE internal_of IS NOT NULL;
CREATE INDEX files_binned_idx    ON files (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX files_binned_with_idx ON files (deleted_with) WHERE deleted_with IS NOT NULL;
CREATE UNIQUE INDEX files_fixed_idx ON files (project_id, fixed) WHERE fixed IS NOT NULL;

-- One row per pointer from a file to a file: what it is for, its place in the order, and where the
-- kind needs it a small JSON (an item's time, the frame it shows). to_file has no foreign key on
-- purpose: a removed file leaves a missing reference, and a restore brings every use back.
CREATE TABLE refs (
  from_file  TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL,                     -- content | item | clip | overlay | base | placed | property | target
  position   INTEGER NOT NULL,                  -- the place in the file's list of references
  to_file    TEXT NOT NULL,
  data       TEXT CHECK (data IS NULL OR json_valid(data)),
  PRIMARY KEY (from_file, kind, position)
);
CREATE INDEX refs_to_idx ON refs (to_file);

-- A property's value on one file. The definition is a file in the project's Settings folder; binning
-- it keeps the values, purging it removes them.
CREATE TABLE property_values (
  file_id        TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  definition_id  TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  value          TEXT NOT NULL CHECK (json_valid(value)),
  PRIMARY KEY (file_id, definition_id)
);
CREATE INDEX property_values_definition_idx ON property_values (definition_id);

-- ---------------------------------------------------------------- admin plane (kept)
-- One snapshot a day, written by the app Worker's cron (storage-stats.ts). workspace_id '' is the
-- bound bucket's total from an R2 listing. No foreign key: the history outlives a deleted workspace.
CREATE TABLE storage_daily (
  day TEXT NOT NULL,                          -- 'YYYY-MM-DD' (UTC)
  workspace_id TEXT NOT NULL DEFAULT '',
  bytes INTEGER NOT NULL,
  objects INTEGER NOT NULL,
  unsized INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (day, workspace_id)
);

-- The admin plane's own settings (the operator's storage marks first); value is JSON.
CREATE TABLE admin_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_by TEXT
);

-- Yesterday's account-wide Cloudflare numbers, kept by the admin Worker's daily cron so the history
-- outlives the GraphQL API's 31-day window. Key/value: a new metric needs no migration.
CREATE TABLE cf_usage_daily (
  day TEXT NOT NULL,
  metric TEXT NOT NULL,
  value REAL NOT NULL,
  taken_at TEXT NOT NULL,
  PRIMARY KEY (day, metric)
);

-- Every change an operator makes in the admin plane, written in the same batch as the change.
-- No foreign key: the trail outlives a deleted account.
CREATE TABLE admin_audit (
  id TEXT PRIMARY KEY,
  at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  operator_email TEXT NOT NULL,
  action TEXT NOT NULL,
  target_user_id TEXT,
  target_email TEXT,
  detail TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX admin_audit_at ON admin_audit (at DESC, id DESC);
